#!/usr/bin/env python3
"""Generate Java and JavaScript quiz banks from twenty picture-book scenarios."""
from pathlib import Path
import json
from stories import STORIES

ROOT=Path(__file__).resolve().parents[1]
JAVA=ROOT/'app/src/main/java/jp/example/dopagaki/StoryData.java'
WEB=ROOT/'web-demo/stories.js'

def js(s):return json.dumps(s,ensure_ascii=False)

lines=[
 'package jp.example.dopagaki;',
 '',
 '/** Generated from tools/stories.py. Do not edit this file manually. */',
 'public final class StoryData {',
 '    private StoryData() {}',
 f'    public static final int POOL_COUNT = {len(STORIES)};',
 '    public static final String[] TITLES = {',
]
for s in STORIES:lines.append('        '+js(s['title'])+',')
lines.extend(['    };', '    static final GameSession.ClipQuestion[][] QUESTION_BANK = {'])
for s in STORIES:
 lines.append('        {')
 for q in s['questions']:
  opts=', '.join(js(x) for x in q['options'])
  lines.append(f'            new GameSession.ClipQuestion({js(q["prompt"])}, new String[]{{{opts}}}, {q["correctIndex"]}, {js(q["explanation"])}),')
 lines.append('        },')
lines.extend(['    };','}'])
JAVA.write_text('\n'.join(lines)+'\n',encoding='utf-8')
WEB.write_text("'use strict';\n// Generated from tools/stories.py. Matching question data for browser.\n(function(root){\n  const STORIES = "+json.dumps(STORIES,ensure_ascii=False,indent=2)+";\n  if(typeof module !== 'undefined' && module.exports) module.exports = STORIES;\n  if(root) root.DopaStories = STORIES;\n})(typeof window !== 'undefined' ? window : null);\n",encoding='utf-8')
print(f'{len(STORIES)} silent story clips, {sum(len(s["questions"]) for s in STORIES)} questions written to Java and JS')
